import{_ as l,l as i,o as a,c as s,v as o,p as d,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"窥孔与窥视窗","description":"","frontmatter":{"title":"窥孔与窥视窗","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/peephole.md","filePath":"cs/peephole.md","lastUpdated":1789023840000}'),h={name:"cs/peephole.md"};function m(_,e,A,u,f,E){const r=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="窥孔与窥视窗" tabindex="-1">窥孔与窥视窗 <a class="header-anchor" href="#窥孔与窥视窗" aria-label="Permalink to &quot;窥孔与窥视窗&quot;">​</a></h1><div class="epigraph"><p>只看相邻几条指令，用代数与控制的局部恒等替换成更短或更快的序列。</p><footer>—— 据 McKeeman, Peephole Optimization, 1965；龙书第 8 章整理</footer></div><p>上一课<a href="/cs/spill-remat">溢出与重物化</a>可能留下冗余传送、比较后多余的测试、或 spill 造成的 load-store 对。本课不重着色。缺口是：<strong>短窗口</strong>改写——窥孔——不需要全局数据流再跑一轮。窗口滑过目标指令（或 IR），模式匹配替换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色与选择各自局部最优，拼接后出现 <code>move r,r</code>、<code>add x,0</code>、跳转到下一指令、<code>store</code> 立刻 <code>load</code> 同地址。全局 CSE 可能已做过，但寄存器分配之后新的垃圾才出现。缺口是分配后的本地清理，不是再插 φ。</p><p>窗口长度常数，故线性一遍或直到无匹配。不保证全局最优；正确性靠每条规则的语义等价（含标志位）。</p><h3 id="窥孔不是数据流" tabindex="-1">窥孔不是数据流 <a class="header-anchor" href="#窥孔不是数据流" aria-label="Permalink to &quot;窥孔不是数据流&quot;">​</a></h3><p>活跃分析看全 CFG。窥孔不求解方程，只认有限模式。有的规则需要「下一指令不是标号目标」之类的局部控制知识，仍不是不动点框架。</p><p><span class="marginnote">McKeeman 1965 命名 peephole。龙书把窥孔放在代码生成之后。本课规则举类不列工业目录。GCC/LLVM 的 InstCombine 是 IR 层同类物。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护长度为 \\(w\\) 的缓冲。规则：恒等运算删除、强度削弱（移位代乘常数，仅当 ISA 有且语义同）、跳转链压缩、死传送。替换后回退窗口以免错过重叠。</p>',11)),(a(),d(c,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%E5%BA%8F%E5%88%97%22%5D%20--%3E%20WIN%5B%22%E9%95%BF%E5%BA%A6%20w%20%E7%9A%84%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WIN%20--%3E%20RUL%5B%22%E6%A8%A1%E5%BC%8F%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20RUL%20--%3E%20MI%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><a href="/cs/riscv-int-isa">RISC-V</a> 上立即数 0、伪指令展开后再窥孔，避免对伪指令与真指令各写一套还不一致。窗口不要跨基本块边界，除非能证明中间没有入口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与流水线：窥孔可消掉无用比较，减少控制冒险来源，但不代替分支预测。与 ABI：不要删掉为遵守调用约定而存在的保存/恢复，除非能证多余——那通常要活跃，超出纯窥孔。安全做法：窥孔不做跨调用的删保存。</p><p>替换可能缩短窗口，应再扫一遍直到稳定，但仍保持局部。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接器、不排指令调度算法（list scheduling）。不改 ABI。后课默认：函数已是可按约定发射的指令。下一课把物理寄存器与栈帧钉成对其他编译单元也成立的二进制接口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窥孔 = 常数窗口上的语义等价改写。</li><li>分配之后尤其需要；线性、不全局最优。</li><li>不擅自删调用保存；窗口默认不跨块。</li><li>出处：McKeeman, 1965；Aho et al., 龙书第 8 章。</li></ul>',8))])}const C=l(h,[["render",m]]);export{b as __pageData,C as default};
